<?php $shareUrl = (isset($_SERVER['HTTPS']) ? 'https' : 'http') . '://' . ($_SERVER['HTTP_HOST'] ?? 'localhost') . url('/noticia/' . $post['slug']); ?>
<article class="article shell"><div class="breadcrumbs"><a href="<?= url('/') ?>">Inicio</a> / <a href="<?= url('/categoria/'.$post['category_slug']) ?>"><?= e($post['category_name']) ?></a></div><header><small><?= e($post['category_name']) ?></small><h1><?= e($post['title']) ?></h1><p class="standfirst"><?= e($post['excerpt']) ?></p><div class="byline">Por <b><?= e($post['author_name']) ?></b> · <?= e(date_es($post['published_at'])) ?></div></header><div class="share-bar" aria-label="Compartir esta noticia"><span>Compartir</span><a class="share-facebook" href="https://www.facebook.com/sharer/sharer.php?u=<?= rawurlencode($shareUrl) ?>" target="_blank" rel="noopener" aria-label="Compartir en Facebook"><img src="<?= asset('images/social/facebook.svg') ?>" alt=""><b>Facebook</b></a><a class="share-x" href="https://twitter.com/intent/tweet?url=<?= rawurlencode($shareUrl) ?>&text=<?= rawurlencode($post['title']) ?>" target="_blank" rel="noopener" aria-label="Compartir en X"><img src="<?= asset('images/social/x.svg') ?>" alt=""><b>X</b></a><a class="share-whatsapp" href="https://wa.me/?text=<?= rawurlencode($post['title'] . ' ' . $shareUrl) ?>" target="_blank" rel="noopener" aria-label="Compartir por WhatsApp"><img src="<?= asset('images/social/whatsapp.svg') ?>" alt=""><b>WhatsApp</b></a><a class="share-email" href="mailto:?subject=<?= rawurlencode($post['title']) ?>&body=<?= rawurlencode($post['title'] . "\n\n" . $shareUrl) ?>" aria-label="Compartir por correo"><img src="<?= asset('images/social/email.svg') ?>" alt=""><b>Correo</b></a><button type="button" data-copy-url="<?= e($shareUrl) ?>" aria-label="Copiar enlace"><img src="<?= asset('images/social/link.svg') ?>" alt=""><b>Copiar enlace</b></button></div><img class="article-image" src="<?= e(post_image($post['image'])) ?>" alt=""><div class="article-body"><?= nl2br(e($post['body'])) ?></div></article>
<section class="shell section"><div class="section-title"><div><small>CONTINÚA LEYENDO</small><h2>Noticias relacionadas</h2></div></div><div class="news-grid"><?php foreach($related as $relatedPost){if($relatedPost['id']===$post['id'])continue;$post=$relatedPost;require __DIR__.'/../partials/card.php';} ?></div></section>
